export default function mergeExamples() {
  const [needed, stock, ingredients, quantities, queen, zeppelin] = [
    [{ Name: "Flour" }, { Name: "Eggs" }, { Name: "Milk" }, { Name: "Lemon" }, { Name: "Sugar" }],
    [{ Name: "Eggs" }, { Name: "Lemon" }, { Name: "Sugar" }],
    [{ Name: "Flour" }, { Name: "Eggs" }, { Name: "Milk" }, { Name: "Lemon" }, { Name: "Sugar" }],
    [
      { Name: "Flour", Quantity: "100g" },
      { Name: "Eggs", Quantity: 2 },
      { Name: "Salt", Quantity: "50g" },
      { Name: "Lemon", Quantity: 1 },
      { Name: "Sugar", Quantity: "6tbsp" },
    ],
    [
      { FirstName: "John", LastName: "Deacon", Instrument: "Drums" },
      {
        FirstName: "Freddy",
        LastName: "Mercury",
        Instrument: "Vocals and Piano",
        Superpower: "Crowd control",
      },
      { FirstName: "Brian", LastName: "May", Instrument: "Guitar" },
      { FirstName: "Roger", LastName: "Taylor", Instrument: "Bass" },
    ],
    [
      { FirstName: "Jimmy", LastName: "Page", Instrument: "Guitar" },
      { FirstName: "Robert", LastName: "Plant", Instrument: "Vocals" },
      { FirstName: "John", LastName: "Bonham", Instrument: "Drums" },
      {
        FirstName: "John",
        LastName: "Paul Jones",
        Instrument: "Bass",
        "Second Instrument": "Keyboard",
      },
    ],
  ];
  const stockNames = new Set(stock.map((x) => x.Name));
  const available = needed
    .filter((x) => stockNames.has(x.Name))
    .map((x) => ({ ...x, ...stock.find((y) => y.Name === x.Name) }));
  const matched = ingredients
    .filter((x) => quantities.some((y) => y.Name === x.Name))
    .map((x) => ({ ...x, ...quantities.find((y) => y.Name === x.Name) }));
  const unmatched = ingredients.filter((x) => !quantities.some((y) => y.Name === x.Name));
  return { available, recipe: [...matched, ...unmatched], band: [...queen, ...zeppelin] };
}
